void NuML_Overlay_DrawText565(void *pvFrameBuffer,
                              uint32_t u32Width,
                              uint32_t u32Height,
                              uint32_t u32X,
                              uint32_t u32Y,
                              const char *szText)
{
    uint16_t *pu16Frame = (uint16_t *)pvFrameBuffer;
    uint32_t u32Col = u32X;
    uint32_t i;

    if ((pu16Frame == NULL) || (szText == NULL))
    {
        return;
    }

    for (i = 0u; szText[i] != '\0'; i++)
    {
        uint8_t u8Char = (uint8_t)szText[i];
        const uint8_t *pu8Glyph;
        uint32_t u32Row;

        if ((u8Char < NUML_OVERLAY_FIRST_CHAR) || (u8Char > NUML_OVERLAY_LAST_CHAR))
        {
            u8Char = (uint8_t)'?';
        }

        /* Clip instead of wrapping: a wrapped line on a video frame is worse
         * than a truncated one. */
        if ((u32Col + NUML_OVERLAY_GLYPH_W) > u32Width)
        {
            break;
        }

        pu8Glyph = &s_au8Font8x16[(uint32_t)(u8Char - NUML_OVERLAY_FIRST_CHAR) * NUML_OVERLAY_GLYPH_H];

        for (u32Row = 0u; u32Row < NUML_OVERLAY_GLYPH_H; u32Row++)
        {
            uint32_t u32PixelY = u32Y + u32Row;
            uint8_t u8Bits;
            uint32_t u32Bit;

            if (u32PixelY >= u32Height)
            {
                break;
            }

            u8Bits = pu8Glyph[u32Row];

            for (u32Bit = 0u; u32Bit < NUML_OVERLAY_GLYPH_W; u32Bit++)
            {
                uint16_t u16Colour = (u8Bits & (uint8_t)(0x80u >> u32Bit))
                                     ? NUML_OVERLAY_FG : NUML_OVERLAY_BG;

                pu16Frame[(u32PixelY * u32Width) + u32Col + u32Bit] = u16Colour;
            }
        }

        u32Col += NUML_OVERLAY_GLYPH_W;
    }
}
